CREATE TABLE "BusinessType" (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    "Type" character varying(50) NOT NULL,
    "Description" character varying(250) NOT NULL,
    CONSTRAINT "PK_BusinessType" PRIMARY KEY (id)
);


CREATE TABLE "CashDrawerShifts" (
    "ShiftId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "OutletId" integer NOT NULL,
    "CashierId" character varying(450) NOT NULL,
    "OpeningFloat" numeric(18,2) NOT NULL,
    "TotalCashSales" numeric(18,2) NOT NULL,
    "TotalCashRefunds" numeric(18,2) NOT NULL,
    "TotalCashIn" numeric(18,2) NOT NULL,
    "TotalCashOut" numeric(18,2) NOT NULL,
    "TotalCashDrops" numeric(18,2) NOT NULL DEFAULT 0.0,
    "ExpectedBalance" numeric(18,2) NOT NULL,
    "ActualCountedBalance" numeric(18,2),
    "Discrepancy" numeric(18,2),
    "Status" character varying(30) NOT NULL,
    "OpenedAt" timestamp with time zone NOT NULL,
    "ClosedAt" timestamp with time zone,
    "Notes" character varying(255),
    CONSTRAINT "PK_CashDrawerShifts" PRIMARY KEY ("ShiftId")
);


CREATE TABLE "CashierSessions" (
    "CashierSessionId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "CashierId" character varying(450) NOT NULL,
    "BranchId" integer NOT NULL,
    "OutletId" integer NOT NULL,
    "DeviceIdentifier" character varying(100),
    "LoginAt" timestamp with time zone NOT NULL,
    "LogoutAt" timestamp with time zone,
    "Status" character varying(30) NOT NULL,
    "LogoutReason" character varying(100),
    "PreviousSessionId" bigint,
    CONSTRAINT "PK_CashierSessions" PRIMARY KEY ("CashierSessionId")
);


CREATE TABLE "CashierSwitchLogs" (
    "SwitchLogId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OutletId" integer NOT NULL,
    "DeviceIdentifier" character varying(100),
    "PreviousCashierId" character varying(450) NOT NULL,
    "NewCashierId" character varying(450) NOT NULL,
    "RequestedAt" timestamp with time zone NOT NULL,
    "CompletedAt" timestamp with time zone NOT NULL,
    "Status" character varying(30) NOT NULL,
    "Reason" character varying(255),
    CONSTRAINT "PK_CashierSwitchLogs" PRIMARY KEY ("SwitchLogId")
);


CREATE TABLE "CashMovementCategories" (
    "CategoryId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Description" character varying(255),
    "MovementType" character varying(30) NOT NULL,
    "RequiresApproval" boolean NOT NULL DEFAULT TRUE,
    "ApprovalThreshold" numeric(18,2) NOT NULL DEFAULT 0.0,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_CashMovementCategories" PRIMARY KEY ("CategoryId")
);


CREATE TABLE "Categories" (
    "CategoryId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(50) NOT NULL,
    "Description" character varying(255),
    "ColorHex" character varying(7) NOT NULL DEFAULT '#2563EB',
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "Categories_pkey" PRIMARY KEY ("CategoryId")
);


CREATE TABLE "DiscountTypes" (
    "DiscountTypeId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" character varying(30) NOT NULL,
    "Name" character varying(100) NOT NULL,
    "DiscountCategory" character varying(30) NOT NULL,
    "DiscountMethod" character varying(20) NOT NULL,
    "DiscountValue" numeric(18,4) NOT NULL,
    "IsStatutory" boolean NOT NULL,
    "RequiresIdentification" boolean NOT NULL,
    "RequiresApproval" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_DiscountTypes" PRIMARY KEY ("DiscountTypeId")
);


CREATE TABLE "HeldSaleAuditLogs" (
    "AuditId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "HeldSaleId" bigint,
    "HoldReference" character varying(50) NOT NULL,
    "CashierId" character varying(450) NOT NULL,
    "BranchId" integer NOT NULL,
    "OutletId" integer NOT NULL,
    "Action" character varying(30) NOT NULL,
    "Details" character varying(255),
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_HeldSaleAuditLogs" PRIMARY KEY ("AuditId")
);


CREATE TABLE "HeldSales" (
    "HeldSaleId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "OutletId" integer NOT NULL,
    "CashierId" character varying(450) NOT NULL,
    "HoldReference" character varying(50) NOT NULL,
    "CustomerName" character varying(200),
    "Notes" character varying(255),
    "Subtotal" numeric(18,2) NOT NULL,
    "DiscountAmount" numeric(18,2) NOT NULL,
    "DiscountCode" character varying(30),
    "CustomerCardNumber" character varying(50),
    "TotalAmount" numeric(18,2) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "ResumedAt" timestamp with time zone,
    CONSTRAINT "PK_HeldSales" PRIMARY KEY ("HeldSaleId")
);


CREATE TABLE "ModifierGroup" (
    modifier_group_id integer GENERATED BY DEFAULT AS IDENTITY,
    name character varying(100) NOT NULL,
    is_required boolean NOT NULL DEFAULT FALSE,
    min_selections integer NOT NULL DEFAULT 0,
    max_selections integer NOT NULL DEFAULT 1,
    display_order integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT TRUE,
    CONSTRAINT "ModifierGroup_pkey" PRIMARY KEY (modifier_group_id)
);


CREATE TABLE "OfflineSyncIdempotency" (
    "SyncId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "LocalTransactionId" character varying(100) NOT NULL,
    "InvoiceNumber" character varying(50) NOT NULL,
    "PayloadHash" character varying(128) NOT NULL,
    "ServerOrderId" bigint NOT NULL,
    "ProcessedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_OfflineSyncIdempotency" PRIMARY KEY ("SyncId")
);


CREATE TABLE "PaymentMethods" (
    payment_method_id integer GENERATED BY DEFAULT AS IDENTITY,
    code character varying(30) NOT NULL,
    name character varying(100) NOT NULL,
    requires_reference boolean NOT NULL DEFAULT FALSE,
    is_active boolean NOT NULL DEFAULT TRUE,
    display_order integer NOT NULL DEFAULT 0,
    CONSTRAINT "PK_PaymentMethods" PRIMARY KEY (payment_method_id)
);


CREATE TABLE "ServiceMode" (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    "Type" character varying(50) NOT NULL,
    "Description" character varying(255) NOT NULL,
    CONSTRAINT "PK_ServiceMode" PRIMARY KEY (id)
);


CREATE TABLE "Taxes" (
    "TaxId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(50),
    "Rate" numeric(18),
    CONSTRAINT "Taxes_pkey" PRIMARY KEY ("TaxId")
);


CREATE TABLE "UnitOfMeasures" (
    "UomId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(50) NOT NULL,
    "Abbreviation" character varying(10) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "UnitOfMeasures_pkey" PRIMARY KEY ("UomId")
);


CREATE TABLE "Users" (
    "UserId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" character varying(50) NOT NULL,
    "PasswordHash" character varying(255) NOT NULL,
    "Role" character varying(20) NOT NULL,
    "PinCode" character varying(10),
    CONSTRAINT "Users_pkey" PRIMARY KEY ("UserId")
);


CREATE TABLE "CashDrawerMovements" (
    "MovementId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ShiftId" bigint NOT NULL,
    "BranchId" integer NOT NULL DEFAULT 1,
    "OutletId" integer NOT NULL DEFAULT 1,
    "MovementType" character varying(30) NOT NULL,
    "CategoryId" integer,
    "CategoryName" character varying(100),
    "Amount" numeric(18,2) NOT NULL,
    "Reason" character varying(255) NOT NULL,
    "ReferenceNumber" character varying(50),
    "ClientMovementId" character varying(100),
    "Status" character varying(30) NOT NULL DEFAULT 'POSTED',
    "CreatedBy" character varying(450),
    "AuthorizedBy" character varying(450) NOT NULL,
    "ApprovedBy" character varying(450),
    "CreatedAt" timestamp with time zone NOT NULL,
    "ApprovedAt" timestamp with time zone,
    "PostedAt" timestamp with time zone,
    "RejectionReason" character varying(255),
    "ReversedBy" character varying(450),
    "ReversedAt" timestamp with time zone,
    "ReversalReason" character varying(255),
    "OriginalMovementId" bigint,
    CONSTRAINT "PK_CashDrawerMovements" PRIMARY KEY ("MovementId"),
    CONSTRAINT "FK_CashDrawerMovements_CashDrawerShifts_ShiftId" FOREIGN KEY ("ShiftId") REFERENCES "CashDrawerShifts" ("ShiftId") ON DELETE CASCADE,
    CONSTRAINT "FK_CashDrawerMovements_CashMovementCategories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "CashMovementCategories" ("CategoryId") ON DELETE SET NULL
);


CREATE TABLE "HeldSaleItems" (
    "HeldSaleItemId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "HeldSaleId" bigint NOT NULL,
    "ProductId" integer NOT NULL,
    "ProductName" character varying(200) NOT NULL,
    "ProductShortCode" character varying(50),
    "Quantity" numeric(18,3) NOT NULL,
    "BasePrice" numeric(18,2) NOT NULL,
    "LineTotal" numeric(18,2) NOT NULL,
    "TaxName" character varying(50) NOT NULL,
    CONSTRAINT "PK_HeldSaleItems" PRIMARY KEY ("HeldSaleItemId"),
    CONSTRAINT "FK_HeldSaleItems_HeldSales" FOREIGN KEY ("HeldSaleId") REFERENCES "HeldSales" ("HeldSaleId") ON DELETE CASCADE
);


CREATE TABLE "ModifierOption" (
    modifier_option_id integer GENERATED BY DEFAULT AS IDENTITY,
    modifier_group_id integer NOT NULL,
    name character varying(100) NOT NULL,
    price numeric(18,2) NOT NULL DEFAULT 0.0,
    display_order integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT TRUE,
    CONSTRAINT "ModifierOption_pkey" PRIMARY KEY (modifier_option_id),
    CONSTRAINT "FK_ModifierOption_ModifierGroup" FOREIGN KEY (modifier_group_id) REFERENCES "ModifierGroup" (modifier_group_id) ON DELETE CASCADE
);


CREATE TABLE "Branches" (
    "BranchId" integer GENERATED BY DEFAULT AS IDENTITY,
    "BusinessTypeId" integer,
    "ServiceModeId" integer,
    "Name" character varying(100) NOT NULL,
    "Code" character varying(20),
    "Address" character varying(255),
    "Phone" character varying(50),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "TaxType" character varying(30) NOT NULL DEFAULT ('VAT-Registered'::character varying),
    "TrackInventory" boolean NOT NULL,
    CONSTRAINT "Branches_pkey" PRIMARY KEY ("BranchId"),
    CONSTRAINT "FK_Branches_BusinessType" FOREIGN KEY ("BusinessTypeId") REFERENCES "BusinessType" (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_Branches_ServiceMode" FOREIGN KEY ("ServiceModeId") REFERENCES "ServiceMode" (id) ON DELETE SET NULL
);


CREATE TABLE "Products" (
    "ProductId" integer GENERATED BY DEFAULT AS IDENTITY,
    "CategoryId" integer NOT NULL,
    "Name" character varying(100) NOT NULL,
    "UnitValue" numeric(10,2),
    "UnitOfMeasure" character varying(20),
    "Barcode" character varying(50),
    "Price" numeric(18,2) NOT NULL,
    "CostPrice" numeric(18,2),
    "SKU" character varying(50),
    "TaxId" integer,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "ImageUrl" character varying(255),
    "ProductType" character varying(20) NOT NULL DEFAULT ('Standard'::character varying),
    "ShortCode" character varying(30),
    "IsKitchenItem" boolean NOT NULL,
    "isDeleted" boolean NOT NULL,
    CONSTRAINT "Products_pkey" PRIMARY KEY ("ProductId"),
    CONSTRAINT "Products_CategoryId_fkey" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("CategoryId"),
    CONSTRAINT "Products_TaxId_fkey" FOREIGN KEY ("TaxId") REFERENCES "Taxes" ("TaxId") ON DELETE SET NULL
);


CREATE TABLE "HeldSaleItemModifiers" (
    "HeldSaleItemModifierId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "HeldSaleItemId" bigint NOT NULL,
    "ModifierOptionId" integer NOT NULL,
    "ModifierName" character varying(100) NOT NULL,
    "AdditionalPrice" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_HeldSaleItemModifiers" PRIMARY KEY ("HeldSaleItemModifierId"),
    CONSTRAINT "FK_HeldSaleItemModifiers_HeldSaleItems" FOREIGN KEY ("HeldSaleItemId") REFERENCES "HeldSaleItems" ("HeldSaleItemId") ON DELETE CASCADE
);


CREATE TABLE "Outlets" (
    "OutletId" integer GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "Name" character varying(100) NOT NULL,
    "DeviceIdentifier" character varying(100),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "PTUNumber" character varying(50),
    "MINNumber" character varying(50),
    "SerialNumber" character varying(50),
    CONSTRAINT "Outlets_pkey" PRIMARY KEY ("OutletId"),
    CONSTRAINT "Outlets_BranchId_fkey" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("BranchId") ON DELETE CASCADE
);


CREATE TABLE "BranchInventory" (
    "BranchInventoryId" integer GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    "StockQuantity" integer NOT NULL,
    "ReorderLevel" integer NOT NULL DEFAULT 5,
    "LastUpdated" timestamp without time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "BranchInventory_pkey" PRIMARY KEY ("BranchInventoryId"),
    CONSTRAINT "BranchInventory_BranchId_fkey" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("BranchId") ON DELETE CASCADE,
    CONSTRAINT "BranchInventory_ProductId_fkey" FOREIGN KEY ("ProductId") REFERENCES "Products" ("ProductId") ON DELETE CASCADE
);


CREATE TABLE "ProductModifierGroup" (
    product_modifier_group_id integer GENERATED BY DEFAULT AS IDENTITY,
    product_id integer NOT NULL,
    modifier_group_id integer NOT NULL,
    display_order integer NOT NULL DEFAULT 0,
    CONSTRAINT "ProductModifierGroup_pkey" PRIMARY KEY (product_modifier_group_id),
    CONSTRAINT "FK_ProductModifierGroup_ModifierGroup" FOREIGN KEY (modifier_group_id) REFERENCES "ModifierGroup" (modifier_group_id) ON DELETE CASCADE,
    CONSTRAINT "FK_ProductModifierGroup_Product" FOREIGN KEY (product_id) REFERENCES "Products" ("ProductId") ON DELETE CASCADE
);


CREATE TABLE "ProductRecipes" (
    "RecipeId" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" integer NOT NULL,
    "RawMaterialProductId" integer NOT NULL,
    "QuantityRequired" numeric(18,4) NOT NULL,
    "Uom" character varying(10),
    CONSTRAINT "ProductRecipes_pkey" PRIMARY KEY ("RecipeId"),
    CONSTRAINT "ProductRecipes_ProductId_fkey" FOREIGN KEY ("ProductId") REFERENCES "Products" ("ProductId") ON DELETE CASCADE,
    CONSTRAINT "ProductRecipes_RawMaterialProductId_fkey" FOREIGN KEY ("RawMaterialProductId") REFERENCES "Products" ("ProductId")
);


CREATE TABLE "StockAdjustments" (
    "StockAdjustmentId" integer GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    "AdjustmentType" character varying(20) NOT NULL,
    "Quantity" integer NOT NULL,
    "PreviousQuantity" integer NOT NULL,
    "NewQuantity" integer NOT NULL,
    "Reason" character varying(255),
    "CreatedAt" timestamp without time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "StockAdjustments_pkey" PRIMARY KEY ("StockAdjustmentId"),
    CONSTRAINT "StockAdjustments_BranchId_fkey" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("BranchId"),
    CONSTRAINT "StockAdjustments_ProductId_fkey" FOREIGN KEY ("ProductId") REFERENCES "Products" ("ProductId")
);


CREATE TABLE "InvoiceSequences" (
    invoice_sequence_id integer GENERATED BY DEFAULT AS IDENTITY,
    outlet_id integer NOT NULL,
    series_code character varying(50) NOT NULL,
    prefix character varying(20),
    starting_number bigint NOT NULL,
    ending_number bigint,
    last_issued_number bigint NOT NULL,
    padding_length integer NOT NULL,
    is_active boolean NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    CONSTRAINT "PK_InvoiceSequences" PRIMARY KEY (invoice_sequence_id),
    CONSTRAINT "FK_InvoiceSequences_Outlet" FOREIGN KEY (outlet_id) REFERENCES "Outlets" ("OutletId") ON DELETE CASCADE
);


CREATE TABLE "OrderSequences" (
    order_sequence_id integer GENERATED BY DEFAULT AS IDENTITY,
    outlet_id integer NOT NULL,
    last_issued_number bigint NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    CONSTRAINT "PK_OrderSequences" PRIMARY KEY (order_sequence_id),
    CONSTRAINT "FK_OrderSequences_Outlet" FOREIGN KEY (outlet_id) REFERENCES "Outlets" ("OutletId") ON DELETE CASCADE
);


CREATE TABLE "Orders" (
    "OrderId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OrderNumber" character varying(30) NOT NULL,
    "BranchId" integer NOT NULL,
    "OutletId" integer NOT NULL,
    "CashierId" character varying(450) NOT NULL,
    "ShiftId" bigint,
    "OrderType" character varying(20) NOT NULL,
    "OrderStatus" character varying(20) NOT NULL,
    "PaymentStatus" character varying(20) NOT NULL,
    "Subtotal" numeric(18,2) NOT NULL,
    "DiscountAmount" numeric(18,2) NOT NULL DEFAULT 0.0,
    "TotalAmount" numeric(18,2) NOT NULL,
    "VatableSales" numeric NOT NULL,
    "VatExemptSales" numeric NOT NULL,
    "ZeroRatedSales" numeric NOT NULL,
    "VatAmount" numeric NOT NULL,
    "DiscountTypeId" integer,
    "DiscountCode" character varying(30),
    "DiscountName" character varying(100),
    "DiscountPercentage" numeric NOT NULL,
    "CustomerCardNumber" character varying(50),
    invoice_sequence_id integer,
    "InvoiceNumber" character varying(50),
    invoice_issued_at timestamp without time zone,
    "CreatedAt" timestamp without time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "CustomerName" character varying(200),
    "CustomerAddress" character varying(255),
    "CustomerTin" character varying(50),
    "CustomerBusinessStyle" character varying(100),
    CONSTRAINT "PK_Orders" PRIMARY KEY ("OrderId"),
    CONSTRAINT "FK_Orders_DiscountTypes_DiscountTypeId" FOREIGN KEY ("DiscountTypeId") REFERENCES "DiscountTypes" ("DiscountTypeId"),
    CONSTRAINT "FK_Orders_InvoiceSequence" FOREIGN KEY (invoice_sequence_id) REFERENCES "InvoiceSequences" (invoice_sequence_id) ON DELETE SET NULL
);


CREATE TABLE "DiscountAuditLogs" (
    "AuditId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" bigint,
    "CashierId" character varying(450) NOT NULL,
    "DiscountCode" character varying(30) NOT NULL,
    "Action" character varying(30) NOT NULL,
    "CustomerCardNumber" character varying(50),
    "DiscountAmount" numeric(18,2) NOT NULL,
    "Reason" character varying(255),
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_DiscountAuditLogs" PRIMARY KEY ("AuditId"),
    CONSTRAINT "FK_DiscountAuditLogs_Orders_OrderId" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("OrderId")
);


CREATE TABLE "OrderItems" (
    "OrderItemId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" bigint NOT NULL,
    "ProductId" integer NOT NULL,
    "ProductName" character varying(200) NOT NULL,
    "ProductShortCode" character varying(30),
    "Quantity" numeric(18,3) NOT NULL,
    "BasePrice" numeric(18,2) NOT NULL,
    "ModifierTotal" numeric(18,2) NOT NULL DEFAULT 0.0,
    "UnitPrice" numeric(18,2) NOT NULL,
    "LineTotal" numeric(18,2) NOT NULL,
    "DiscountAmount" numeric NOT NULL,
    "VatType" character varying(20) NOT NULL,
    "VatAmount" numeric NOT NULL,
    CONSTRAINT "PK_OrderItems" PRIMARY KEY ("OrderItemId"),
    CONSTRAINT "FK_OrderItems_Orders" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("OrderId") ON DELETE CASCADE
);


CREATE TABLE "Payments" (
    "PaymentId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" bigint NOT NULL,
    "PaymentMethod" character varying(30) NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "AmountTendered" numeric(18,2) NOT NULL,
    "ChangeAmount" numeric(18,2) NOT NULL,
    "PaymentStatus" character varying(20) NOT NULL,
    "ReferenceNumber" character varying(100),
    "ProcessedBy" character varying(450) NOT NULL,
    "PaidAt" timestamp without time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Payments" PRIMARY KEY ("PaymentId"),
    CONSTRAINT "FK_Payments_Orders" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("OrderId") ON DELETE CASCADE
);


CREATE TABLE "ReceiptReprintLogs" (
    "ReprintLogId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" bigint NOT NULL,
    "InvoiceNumber" character varying(50),
    "BranchId" integer NOT NULL,
    "OutletId" integer NOT NULL,
    "CashierId" character varying(450) NOT NULL,
    "ReprintReason" character varying(255) NOT NULL,
    "ReprintedAt" timestamp with time zone NOT NULL,
    "PrinterName" character varying(100),
    "PrintStatus" character varying(30) NOT NULL,
    "ErrorMessage" text,
    CONSTRAINT "PK_ReceiptReprintLogs" PRIMARY KEY ("ReprintLogId"),
    CONSTRAINT "FK_ReceiptReprintLogs_Orders" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("OrderId") ON DELETE CASCADE
);


CREATE TABLE "SalesReturns" (
    "ReturnId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OriginalOrderId" bigint NOT NULL,
    "BranchId" integer NOT NULL,
    "OutletId" integer NOT NULL,
    "ReturnReference" character varying(50) NOT NULL,
    "ReturnReason" character varying(255) NOT NULL,
    "Status" character varying(30) NOT NULL,
    "RequestedBy" character varying(450) NOT NULL,
    "ApprovedBy" character varying(450),
    "TotalRefundAmount" numeric(18,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CompletedAt" timestamp with time zone,
    CONSTRAINT "PK_SalesReturns" PRIMARY KEY ("ReturnId"),
    CONSTRAINT "FK_SalesReturns_Orders_OriginalOrderId" FOREIGN KEY ("OriginalOrderId") REFERENCES "Orders" ("OrderId") ON DELETE RESTRICT
);


CREATE TABLE "TransactionVoids" (
    "VoidId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OriginalOrderId" bigint NOT NULL,
    "OriginalInvoiceNumber" character varying(50),
    "VoidReason" character varying(255) NOT NULL,
    "RequestedBy" character varying(450) NOT NULL,
    "ApprovedBy" character varying(450) NOT NULL,
    "RequestedAt" timestamp with time zone NOT NULL,
    "ApprovedAt" timestamp with time zone NOT NULL,
    "VoidedAt" timestamp with time zone NOT NULL,
    "Status" character varying(30) NOT NULL,
    "ReversalReference" character varying(50),
    CONSTRAINT "PK_TransactionVoids" PRIMARY KEY ("VoidId"),
    CONSTRAINT "FK_TransactionVoids_Orders_OriginalOrderId" FOREIGN KEY ("OriginalOrderId") REFERENCES "Orders" ("OrderId") ON DELETE RESTRICT
);


CREATE TABLE "OrderItemModifiers" (
    "OrderItemModifierId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OrderItemId" bigint NOT NULL,
    "ModifierOptionId" integer NOT NULL,
    "ModifierName" character varying(100) NOT NULL,
    "AdditionalPrice" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_OrderItemModifiers" PRIMARY KEY ("OrderItemModifierId"),
    CONSTRAINT "FK_OrderItemModifiers_OrderItems" FOREIGN KEY ("OrderItemId") REFERENCES "OrderItems" ("OrderItemId") ON DELETE CASCADE
);


CREATE TABLE "SalesReturnItems" (
    "ReturnItemId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ReturnId" bigint NOT NULL,
    "OriginalOrderItemId" bigint NOT NULL,
    "Quantity" numeric(18,3) NOT NULL,
    "OriginalUnitPrice" numeric(18,2) NOT NULL,
    "AllocatedDiscount" numeric(18,2) NOT NULL,
    "AllocatedTax" numeric(18,2) NOT NULL,
    "RefundAmount" numeric(18,2) NOT NULL,
    "RestockDisposition" character varying(30) NOT NULL,
    CONSTRAINT "PK_SalesReturnItems" PRIMARY KEY ("ReturnItemId"),
    CONSTRAINT "FK_SalesReturnItems_OrderItems_OriginalOrderItemId" FOREIGN KEY ("OriginalOrderItemId") REFERENCES "OrderItems" ("OrderItemId") ON DELETE RESTRICT,
    CONSTRAINT "FK_SalesReturnItems_SalesReturns_ReturnId" FOREIGN KEY ("ReturnId") REFERENCES "SalesReturns" ("ReturnId") ON DELETE CASCADE
);


CREATE TABLE "Refunds" (
    "RefundId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ReturnId" bigint,
    "VoidId" bigint,
    "OriginalPaymentId" bigint NOT NULL,
    "RefundMethod" character varying(30) NOT NULL,
    "RefundAmount" numeric(18,2) NOT NULL,
    "ReferenceNumber" character varying(100),
    "Status" character varying(30) NOT NULL,
    "RequestedAt" timestamp with time zone NOT NULL,
    "CompletedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Refunds" PRIMARY KEY ("RefundId"),
    CONSTRAINT "FK_Refunds_Payments_OriginalPaymentId" FOREIGN KEY ("OriginalPaymentId") REFERENCES "Payments" ("PaymentId") ON DELETE RESTRICT,
    CONSTRAINT "FK_Refunds_SalesReturns_ReturnId" FOREIGN KEY ("ReturnId") REFERENCES "SalesReturns" ("ReturnId") ON DELETE SET NULL,
    CONSTRAINT "FK_Refunds_TransactionVoids_VoidId" FOREIGN KEY ("VoidId") REFERENCES "TransactionVoids" ("VoidId") ON DELETE SET NULL
);


CREATE INDEX "IX_Branches_BusinessTypeId" ON "Branches" ("BusinessTypeId");


CREATE INDEX "IX_Branches_ServiceModeId" ON "Branches" ("ServiceModeId");


